-- ######################## DIN-EN-16941-2-01 · Registrierung, Anwendungsbereich, Begriffe und funktionale Elemente ########################
-- vorgesehene_nutzung
update public.fields set verification_status='verified_against_standard', verification_quote='Sie ist insbesondere anwendbar für die Nutzung von behandeltem Grauwasser zur: - WC-Spülung; - Gartenbewässerung; - Reinigung von Wäsche; - Reinigung von Gegenständen. | Vom Anwendungsbereich dieses Dokuments ausgenommen sind: - die Verwendung als Trinkwasser und zur Zubereitung von Speisen; - die Verwendung für die Körperhygiene; - direkte Anwendungssysteme ohne Aufbereitung; — printed p.6', verification_note='md-verified 2026-09-05 (§1, printed p.6 derived) [VC] — enum = the four §1 uses verbatim; Tab. D.1/D.2 additionally split "Sprühanwendung" (Hochdruckreinigung, Gartensprenger, Autowäsche) from non-spray use — the enum has no spray token (STAGED S-1)', verified_at=now() where id='f7ea931c-f8e9-492f-8a39-129d9eb6e1e3' and verification_status not in ('verified_against_standard','corrected');
-- anlagentyp
update public.fields set verification_status='verified_against_standard', verification_quote='Grauwassernutzungsanlagen unterscheiden sich erheblich nach Komplexität und Größe und können nach der Art der Behandlung wie folgt klassifiziert werden: a) Anlagen für die direkte Nutzung (ohne Behandlung) [...] b) Anlagen mit kurzzeitiger Rückhaltung [...] c) einfache physikalische/chemische Anlagen [...] d) biologische Anlagen [...] e) biologisch-mechanische Anlagen | Die verschiedenen Arten von Grauwassersystemen können nach Anhang B unterschieden werden. — printed p.26 / p.8', verification_note='md-verified 2026-09-05 (Anhang B / §5.1, printed p.26 / p.8 derived) [VC] — clause_reference §4 — the list lives in Anhang B (informativ), cited from §5.1 (retag STAGED S-7); option a) "direkt" is outside the §1 scope ("direkte Anwendungssysteme ohne Aufbereitung" excluded) — STAGED S-10', verified_at=now() where id='af8a8b3c-21aa-44d4-a23e-8fad2965db9d' and verification_status not in ('verified_against_standard','corrected');
-- grauwasser_herkunft
update public.fields set verification_status='verified_against_standard', verification_quote='Menge und Verschmutzung der unterschiedlichen Arten von Grauwasser hängen von dessen Herkunft ab. Der Verschmutzungsgrad von Grauwasser aus Küchenspüle oder Geschirrspüler ist höher, als der von gering verschmutztem Grauwasser und kann eine intensivere Behandlung erfordern. | Zur Reduktion des Behandlungsaufwands sollte die Sammlung wie folgt präferiert werden: e) Duschen und Badewannen; f) Handwaschbecken; g) Waschmaschinen; h) Küchenspülen und/oder Geschirrspüler. — printed p.8 / p.18', verification_note='md-verified 2026-09-05 (§4 / §6.2.2, printed p.8 / p.18 derived) [VC] — the six source tokens are the §6.2.2 e)-h) list (§4 names only Küchenspüle/Geschirrspüler) — retag STAGED S-7', verified_at=now() where id='6dc5b4ba-281d-4f84-a6d8-f647ae8d716f' and verification_status not in ('verified_against_standard','corrected');
-- betriebssicherheit_gewaehrleistet
update public.fields set verification_status='verified_against_standard', verification_quote='Grauwassernutzungsanlagen müssen so geplant, eingebaut, gekennzeichnet, betrieben und gewartet werden, dass die notwendige Betriebssicherheit jederzeit sichergestellt ist und die erforderlichen Arbeiten zur Instandhaltung leicht durchgeführt werden können. — printed p.8', verification_note='md-verified 2026-09-05 (§4, printed p.8 derived) [VC]', verified_at=now() where id='14aecb80-21c8-4bd5-8c3d-104bd9445e52' and verification_status not in ('verified_against_standard','corrected');
-- ueberflutungsschutz
update public.fields set verification_status='verified_against_standard', verification_quote='Grauwassernutzungsanlagen dürfen keine Überflutungen verursachen und müssen deshalb potentielle Umgehungen und/oder angemessen dimensionierte Überläufe umfassen. — printed p.8', verification_note='md-verified 2026-09-05 (§4, printed p.8 derived) [VC]', verified_at=now() where id='cbe025c5-5e96-4dd4-9d21-16a94cbb0ca7' and verification_status not in ('verified_against_standard','corrected');

-- ######################## DIN-EN-16941-2-02 · Planung: Sammlung, Behandlung, Speicherung, Nachspeisung, Pumpen und Steuerung ########################
-- getrennte_sammlung
update public.fields set verification_status='verified_against_standard', verification_quote='Grauwasser muss in separaten Abwasserleitungssystemen gesammelt werden und von den Sammeleinrichtungen durch Schwerkraft zum Grauwassersystem fließen können. Falls dies nicht möglich ist, sind Pumpen vorzusehen (siehe 5.6). — printed p.9', verification_note='md-verified 2026-09-05 (§5.2, printed p.9 derived) [VC]', verified_at=now() where id='645d32a0-e546-4dd2-8f04-9a48bdf0e241' and verification_status not in ('verified_against_standard','corrected');
-- sammlung_bemessung_en12056
update public.fields set verification_status='verified_against_standard', verification_quote='Sammelrohrsysteme müssen a) für Grauwasser geeignet sein; b) nach EN 12056-2 in der Weise bemessen und ausgelegt sein, dass Schaumbildung minimiert wird. Da Lufteintrag ein wesentlicher Grund für Schaumbildung ist, müssen Verwirbelungen und Rohrbögen minimiert werden; c) gekennzeichnet sein (siehe Abschnitt 8); und d) einen freien Ablauf ermöglichen, um Stagnation zu vermeiden. — printed p.9', verification_note='md-verified 2026-09-05 (§5.2 b), printed p.9 derived) [VC] — "muss" with no gate — STAGED S-6', verified_at=now() where id='317552d5-d801-4a16-9a6f-2dcca899e645' and verification_status not in ('verified_against_standard','corrected');
-- bypass_vorhanden
update public.fields set verification_status='verified_against_standard', verification_quote='Das Grauwassersystem sollte mindestens mit einem Bypass ausgestattet sein, der es ermöglicht, das Grauwasser während Wartungsmaßnahmen, Verstopfungen oder Systemtrennungen, direkt in die Abwasserleitung einzuspeisen. Die Einleitung aus dem Bypass darf das Abwassersystem nicht überlasten. | d) sicherstellen, dass der Bypass unbehandeltes Grauwasser in das Schmutzwassersystem ableitet, — printed p.9 / p.17', verification_note='md-verified 2026-09-05 (§5.2 / §5.7 d), printed p.9 / p.17 derived) [VC] — §5.2 is "sollte"; §5.7 d) presupposes the bypass under "muss" — CR-02 severity STAGED S-5', verified_at=now() where id='5ffa1f67-d4d1-4983-891f-e2c70d9c1a42' and verification_status not in ('verified_against_standard','corrected');
-- behandlungsstufen
update public.fields set verification_status='verified_against_standard', verification_quote='Behandlungsarten müssen einen oder mehrere der folgenden Teilschritte einschließen: a) Sedimentation/Flotation, z. B. mittels Absetzbehältern; b) Siebung, z. B. Zurückhalten von groben Partikeln; c) mechanische Filtration von Feinpartikeln, z. B. Membranfiltration; d) biologische Behandlung, z. B. Belüftung; e) chemische Behandlung, z. B. Fällung; f) Desinfektion, z. B. Ultraviolettbestrahlung (UV). — printed p.10', verification_note='md-verified 2026-09-05 (§5.3, printed p.10 derived) [VC] — source says "einen oder mehrere" — a multi-select; the field is a single enum', verified_at=now() where id='67de9924-e11d-471f-a322-c7601d65fed3' and verification_status not in ('verified_against_standard','corrected');
-- behandlung_erreicht_qualitaet
update public.fields set verification_status='verified_against_standard', verification_quote='Das gesammelte Grauwasser muss mindestens in dem Maße behandelt werden, wie es für die Erreichung der Wasserqualitätsanforderungen der angestrebten Nutzung notwendig ist (siehe Anhang D). — printed p.10', verification_note='md-verified 2026-09-05 (§5.3, printed p.10 derived) [VC]', verified_at=now() where id='fbd4b11a-65bb-484f-ac45-96707fd9ac1f' and verification_status not in ('verified_against_standard','corrected');
-- speicher_werkstoff
update public.fields set verification_status='verified_against_standard', verification_quote='Die Werkstoffe (z. B. Beton, Stahl, Polyvinylchlorid (PVC-U), Polyethylen (PE), Polypropylen (PP), glasfaserverstärkter Kunststoff (GRP-UP)), die für Speichereinrichtungen verwendet werden, müssen den in EN 12566-3 beschriebenen Werkstoffeigenschaften entsprechen. Werkstoffe für Bauteile in Kontakt mit Wasser müssen korrosionsbeständig sein. — printed p.10', verification_note='md-verified 2026-09-05 (§5.4.2, printed p.10 derived) [VC] — the six tokens are the source''s "z. B." examples, not a closed list', verified_at=now() where id='c3ff0e80-6895-40f3-8d64-46a1a2c37ed7' and verification_status not in ('verified_against_standard','corrected');
-- speicher_lichtundurchlaessig
update public.fields set verification_status='verified_against_standard', verification_quote='Die verwendeten Werkstoffe dürfen keinen negativen Einfluss auf die Qualität des gespeicherten Wassers und die Umgebung der Anlage haben. Die Speichereinrichtung muss aus lichtundurchlässigem Werkstoff bestehen. — printed p.10', verification_note='md-verified 2026-09-05 (§5.4.2, printed p.10 derived) [VC]', verified_at=now() where id='52883534-b7bd-4822-9d4c-6a2218cabc23' and verification_status not in ('verified_against_standard','corrected');
-- nennkapazitaet
update public.fields set verification_status='verified_against_standard', verification_quote='Die Nennkapazität ist das maximale Wasservolumen, das in der Speichereinrichtung zurückgehalten werden kann, und ist vom Hersteller oder Planer anzugeben. | Die Kapazität kann gemessen oder berechnet werden. — printed p.11', verification_note='md-verified 2026-09-05 (§5.4.4, printed p.11 derived) [VC] — unit "l" is the encoding''s choice; the source prints no unit', verified_at=now() where id='8c7fa800-afb8-44c0-a7f9-fcf3728c70ae' and verification_status not in ('verified_against_standard','corrected');
-- standsicherheit_nachgewiesen
update public.fields set verification_status='verified_against_standard', verification_quote='Unterirdische Speichereinrichtungen müssen auftretenden Höchstlasten und Belastungen während Betrieb, Einbau, Nutzung und Wartung standhalten. Dies muss entweder durch Berechnung oder Prüfung erfolgen. | Oberirdische Speichereinrichtungen müssen der Wirkung von hydrostatischem Druck ohne übermäßige Verformung standhalten, ohne dass ihre Funktion nachteilig beeinflusst wird. Dies muss entweder durch Berechnung oder Prüfung erfolgen. — printed p.11', verification_note='md-verified 2026-09-05 (§5.4.5, printed p.11 derived) [VC]', verified_at=now() where id='eebee95e-9f26-4b49-a172-1e636d3cbeb1' and verification_status not in ('verified_against_standard','corrected');
-- wasserdichtheit_nachgewiesen
update public.fields set verification_status='verified_against_standard', verification_quote='Die Speichereinrichtung muss wasserdicht sein hinsichtlich - der Wände, aus denen sie besteht, - der Kupplungen für die hydraulischen Anschlüsse und - der Wanddurchführungen, die gegebenenfalls für elektrische Kabel genutzt werden. — printed p.11', verification_note='md-verified 2026-09-05 (§5.4.6, printed p.11 derived) [VC]', verified_at=now() where id='d8e38daf-3d9c-4671-8f78-62863f101050' and verification_status not in ('verified_against_standard','corrected');
-- zugang_oeffnung_mm
update public.fields set verification_status='verified_against_standard', verification_quote='Für den Personenzugang müssen die Maße nach EN 476 berücksichtigt werden. Wenn kein Personenzugang vorgesehen ist, muss eine Öffnung (d.h. Breite einer rechtwinkligen oder Durchmesser einer runden Öffnung) mit mindestens 400 mm vorhanden sein. — printed p.11', verification_note='md-verified 2026-09-05 (§5.4.8, printed p.11 derived) [VC] — printed hard limit 400 mm has no gate — STAGED S-6', verified_at=now() where id='ef7da1f5-e52c-476f-a0b0-f4beea439353' and verification_status not in ('verified_against_standard','corrected');
-- ueberlauf_vorhanden
update public.fields set verification_status='verified_against_standard', verification_quote='Alle Speichereinrichtungen müssen mit einem Überlauf ausgestattet sein, der überschüssiges Wasser in ein Entwässerungssystem ableiten kann. Der Überlauf in einen Abwasserkanal muss mit einem Geruchsverschluss versehen sein. | Gegen Rückfluss aus der Kanalisation muss ein Schutz nach EN 13564-1 vorgesehen werden. | Eine geeignete Sicherung gegen das Eindringen von Kleintieren muss vorgesehen werden. — printed p.12', verification_note='md-verified 2026-09-05 (§5.4.9, printed p.12 derived) [VC] — "müssen" with no gate — STAGED S-6', verified_at=now() where id='53619e73-a15a-4c3d-9f97-ec0a3cd5c377' and verification_status not in ('verified_against_standard','corrected');
-- ueberlauf_kapazitaet
update public.fields set verification_status='verified_against_standard', verification_quote='Die Kapazität des Überlaufs muss größer oder gleich sein wie die des Zuflusses. | Jegliche Schutzvorrichtung darf den wirksamen Querschnitt des Überlaufs nicht verringern. — printed p.12', verification_note='md-verified 2026-09-05 (§5.4.9, printed p.12 derived) [VC] — unit "l/s" is the encoding''s choice; the source prints no unit for the overflow capacity', verified_at=now() where id='05b23fbb-331e-49fc-9a51-0a1e3accd67e' and verification_status not in ('verified_against_standard','corrected');
-- zufluss_kapazitaet
update public.fields set verification_status='verified_against_standard', verification_quote='Die Kapazität des Überlaufs muss größer oder gleich sein wie die des Zuflusses. | Zum Beispiel kann eine Dusche einen Abfluss zwischen $0,1 \mathrm{l} / \mathrm{s}$ (oder weniger) und $0,3 \mathrm{l} / \mathrm{s}$ aufweisen, während eine volle Badewanne typischerweise einen Abfluss zwischen $0,4 \mathrm{l} / \mathrm{s}$ und $0,5 \mathrm{l} / \mathrm{s}$ aufweist. Das Grauwassersystem muss in der Lage sein, solche schwankenden Zulaufraten zu bewältigen. — printed p.12 / p.8', verification_note='md-verified 2026-09-05 (§5.4.9 / §5.1, printed p.12 / p.8 derived) [VC] — partly supported: the source names the Zufluss only as the comparator of §5.4.9; l/s follows the §5.1 example flow rates', verified_at=now() where id='4f512558-8536-4f69-8481-c6bc763cb0c7' and verification_status not in ('verified_against_standard','corrected');
-- nachspeisung_vorhanden
update public.fields set verification_status='verified_against_standard', verification_quote='Die Grauwasserbehandlungsanlage muss eine Nachspeisung haben, wenn kontinuierlich Wasser benötigt wird. Das nachgespeiste Wasser kann eingeleitet werden in - eine Speicherzisterne, die der Pumpe vorgelagert ist, zur Abgabe in die Verteilungsleitungen, z. B. ein speziell angefertigtes Modul, oder - eine Zwischenspeicherzisterne, die üblicherweise höher gelagert ist, z. B. Eigendruckversorgung, oder - eine Speichereinrichtung für behandeltes Grauwasser. — printed p.12', verification_note='md-verified 2026-09-05 (§5.5.1, printed p.12 derived) [VC]', verified_at=now() where id='d1a37df9-6f10-4e59-b3eb-0b26c8798798' and verification_status not in ('verified_against_standard','corrected');
-- nachspeisung_steuerung_auto
update public.fields set verification_status='verified_against_standard', verification_quote='Wenn der Wasserstand der Speichereinrichtung unter einen gegebenen Mindeststand fällt, muss die Steuerung der Nachspeisung automatisch die Betriebssicherheit der Anlage sicherstellen. Das kann auch durch eine Steuereinrichtung erreicht werden (siehe 5.7). | Die Nachspeisung muss mit einem Steuerungsmechanismus ausgerüstet sein, der sicherstellt, dass die bereitgestellte Wassermenge auf das für die sofortige Entnahme Notwendige reduziert wird. — printed p.12–13', verification_note='md-verified 2026-09-05 (§5.5.1, printed p.12–13 derived) [VC] — "muss" with no gate — STAGED S-6', verified_at=now() where id='bc58a37e-692f-4329-ae93-3b22f6222ecb' and verification_status not in ('verified_against_standard','corrected');
-- rueckflusssicherung_typ
update public.fields set verification_status='verified_against_standard', verification_quote='Um zu verhindern, dass Nicht-Trinkwasser in die Trinkwasser- oder öffentliche Wasserversorgung eindringt, muss die Nachspeisung mit einer Sicherungseinrichtung ausgestattet sein, die gegen Verunreinigung durch Flüssigkeiten der Kategorie 5 (freier Auslauf) nach EN 1717 absichert, wie beschrieben in: - EN 13076, Familie A, Typ A, „AA Ungehinderter freier Auslauf“ Rohrtrenner (siehe Bild 2): [...] - EN 13077, Familie A Typ B, „AB Freier Auslauf mit nicht kreisförmigem Überlauf“ Rohrtrenner (siehe Bild 3): — printed p.13', verification_note='md-verified 2026-09-05 (§5.5.2, printed p.13 derived) [VC]', verified_at=now() where id='1ea8728b-0e79-4ee4-aeca-d37a8a26ecb4' and verification_status not in ('verified_against_standard','corrected');
