-- pumpensteuerung_handnot
update public.fields set verification_status='verified_against_standard', verification_quote='Pumpen müssen mit einer Pumpensteuerung zur automatischen Kontrolle des Pumpenbetriebs, einschließlich einer Handnotbetätigung, ausgestattet sein. Die Steuerung muss manuelle Bedienung ermöglichen. | Die Pumpensteuerung muss - Pumpen steuern und Verschleiß und Energieverbrauch minimieren, und - die Pumpen vor Trockenlauf schützen. — printed p.16', verification_note='md-verified 2026-09-05 (§5.6.5, printed p.16 derived) [VC] — "müssen" with no gate — STAGED S-6', verified_at=now() where id='8342abb3-8b60-4bcd-bb26-6f4898c9a75f' and verification_status not in ('verified_against_standard','corrected');
-- anlagensteuerung_vorhanden
update public.fields set verification_status='verified_against_standard', verification_quote='Eine Anlagensteuerung muss in der Grauwasseranlage vorhanden sein, um sicherzustellen, dass die Benutzer zumindest darüber informiert werden, ob die Anlage funktioniert. | Die Anlagensteuerung muss a) den Nutzer/Bediener informieren, wenn Verbrauchsmaterial aufgefüllt oder erneuert werden muss, um eine Fehlfunktion zu vermeiden, b) sicherstellen, dass behandeltes Grauwasser nicht über eine Zeitdauer gespeichert wird, die zu einer Verschlechterung der Wasserqualität im Vergleich zur festgelegten Qualität führt (siehe Abschnitt 10) oder die Anforderungen des Herstellers überschreitet, c) bei jeglicher Fehlfunktion: den Nutzer/Bediener informieren, z. B. durch ein sichtbares oder akustisches Warnsignal, [...] — printed p.17', verification_note='md-verified 2026-09-05 (§5.7, printed p.17 derived) [VC]', verified_at=now() where id='76568df5-9e38-4103-9a70-9739ada09d16' and verification_status not in ('verified_against_standard','corrected');
-- anlagensteuerung_bms_ausgang
update public.fields set verification_status='verified_against_standard', verification_quote='Die Anlagensteuerung muss [...] h) über einen spannungsfreien Ausgang zum Anschluss des Grauwassersystems an ein Gebäudemanagementsystem (BMS) verfügen, wenn zweckdienlich. — printed p.17', verification_note='md-verified 2026-09-05 (§5.7 h), printed p.17 derived) [VC] — the description''s "Schnittstelle zu VDI 3814" is NOT in the source (VDI 3814 appears nowhere in the md) — invented cross-reference, STAGED S-8', verified_at=now() where id='3cc0e155-d925-414b-ad35-afccc9c13268' and verification_status not in ('verified_against_standard','corrected');
-- wasserzaehler_vorgesehen
update public.fields set verification_status='verified_against_standard', verification_quote='Wenn Wasserzähler zur Erfassung der verwendeten Menge an Grauwasser im Gebäude und dessen Ableiten in die öffentliche Kanalisation gefordert werden, müssen die Festlegungen nach EN ISO 4064-1 bis EN ISO 4064-5 beachtet werden. — printed p.17', verification_note='md-verified 2026-09-05 (§5.8, printed p.17 derived) [VC]', verified_at=now() where id='14851739-f845-4b0e-9ab6-56cd8cd27535' and verification_status not in ('verified_against_standard','corrected');
-- keine_querverbindungen_verteilung
update public.fields set verification_status='verified_against_standard', verification_quote='Die durchgeführte Verteilung muss die Unversehrtheit und den Schutz von öffentlichen und privaten Trinkwasserverteilungsanlagen sicherstellen. | Querverbindungen zwischen Nicht-Trinkwasser-Rohrleitungssystemen und anderen Rohrleitungssystemen sind nicht zulässig. — printed p.17', verification_note='md-verified 2026-09-05 (§5.9, printed p.17 derived) [VC]', verified_at=now() where id='95599fab-e339-41d5-ad4f-3f7fa74aa8cc' and verification_status not in ('verified_against_standard','corrected');

