-- berechnungsverfahren
update public.fields set verification_status='verified_against_standard', verification_quote='Die Art und Kapazität des Grauwassersystems sollte nach einer der folgenden Methoden berechnet werden: a) ein vereinfachtes Verfahren, bei dem das im Bad anfallende Grauwasser zur Toilettenspülung und/oder zum Reinigen der Wäsche innerhalb einer Wohneinheit verwendet wird (siehe 6.2.3); b) ein differenziertes Verfahren, bei dem das im Bad anfallende Grauwasser z. B. zur Toilettenspülung, zum Reinigen der Wäsche und zur Gartenbewässerung in Wohn-, Gewerbe-, Industrie- und öffentlichen Gebäuden verwendet wird (siehe 6.2.4). | Das vereinfachte Verfahren beruht auf der Abwägung folgender Annahmen und ist nur für Wohngebäude anwendbar: — printed p.18 / p.19', verification_note='md-verified 2026-09-05 (§6.2.1 / §6.2.3, printed p.18 / p.19 derived) [VC] — the worksheet materialises only the differentiated method; the simplified method (§6.2.3, Tab. A.1: 60/35/15/10 l per person) has no fields — STAGED S-9', verified_at=now() where id='1aa25f4c-4561-47cd-85f0-ce841109521d' and verification_status not in ('verified_against_standard','corrected');
