-- bemessungswert_massgebend
update public.fields set verification_status='verified_against_standard', verification_quote='Für die Gesamtauslegung des Systems muss der niedrigste berechnete Wert für den Ertrag oder den Bedarf verwendet werden. Es wird empfohlen, die Speicherung von behandeltem Grauwasser zu minimieren. Da es im Allgemeinen eine unbegrenzte Nachlieferung von nicht behandeltem Grauwasser gibt, wird normalerweise eine Speicherung in Höhe von bis zu 50 \% des Tagesbedarfs ausreichend sein. — printed p.18', verification_note='md-verified 2026-09-05 (§6.1, printed p.18 derived) [VC] — derived quantity (min of Y_G, D_G) that is hand-enterable — no equation, CR-12 checks presence only (STAGED S-3)', verified_at=now() where id='f893ecb3-2391-46fd-8a81-1745d07fc13b' and verification_status not in ('verified_against_standard','corrected');

-- ######################## DIN-EN-16941-2-04 · Einbau, Kennzeichnung, Inbetriebnahme und Wasserqualitaetspruefung ########################
-- abstand_wurzeln_m
update public.fields set verification_status='verified_against_standard', verification_quote='Die Position der unterirdischen Speichereinrichtung muss einen Mindestabstand von 3 m von Bäumen oder Pflanzen einhalten, die ein größeres Wurzelsystem ausbilden. Eine Rasenfläche ist erlaubt. Pflanzen mit weniger als 3 m Abstand von der Speichereinrichtung können den Einbau von Wurzelschutz erfordern. — printed p.21', verification_note='md-verified 2026-09-05 (§7, printed p.21 derived) [VC] — applies to UNDERGROUND tanks only and the source allows < 3 m with Wurzelschutz — CR-13 (block, unconditional) over-enforces, STAGED S-4', verified_at=now() where id='dcbcca56-f563-4f90-971d-9ae5da488f14' and verification_status not in ('verified_against_standard','corrected');
-- kennzeichnung_nicht_trinkwasser
update public.fields set verification_status='verified_against_standard', verification_quote='Alle Rohre (sowohl zur Sammlung und zur Verteilung), Anschlüsse und Entnahmestellen für NichtTrinkwasser müssen beschriftet und beschildert sein, [...] - Entnahmestellen für Nicht-Trinkwasser müssen durch die Worte „Kein Trinkwasser“ oder durch ein Warnzeichen, wie in Bild 4 gezeigt, identifiziert werden. [...] | - Die Rohre für das Nicht-Trinkwasserverteilungssystem müssen deutlich erkennbar sein; dies kann durch eine von Trinkwasserrohren abweichende Farbe oder Rohrmarkierung erreicht werden. - In der Nähe des Hauptabsperrventils der Trinkwasserzuleitung muss ein Schild mit einem Hinweis auf das vorhandene Nicht-Trinkwassersystem angebracht werden. — printed p.22', verification_note='md-verified 2026-09-05 (§8, printed p.22 derived) [VC] — one boolean covers three separate "muss" marking duties (outlets, pipes, sign at the main shut-off)', verified_at=now() where id='ec02c281-9e3a-42eb-8a4e-4487d3c1b470' and verification_status not in ('verified_against_standard','corrected');
-- querverbindungstest_ergebnis
update public.fields set verification_status='verified_against_standard', verification_quote='Das Sammlungs- und Verteilungssystem muss gespült werden und auf Wasserdichtheit (siehe EN 806-4, EN 12056-5, EN 1610) und Querverbindungen zwischen Trink- und Nicht-Trinkwasserleitungen, entweder durch einen Test mit Farbstoff (siehe Beispiel in Anhang C) oder durch einen Drucktest, untersucht werden. | - Ventile für Nicht-Trinkwasser zeigen gefärbtes Wasser: BESTANDEN; - Ventile für Trinkwasser mit gefärbtem oder nicht-gefärbtem Wasser: NICHT BESTANDEN; nicht zulässige Querverbindung zwischen Trinkwasser- und Nicht-TrinkwasserVerteilungssystem. — printed p.23 / p.27', verification_note='md-verified 2026-09-05 (§9 / Anhang C, printed p.23 / p.27 derived) [VC]', verified_at=now() where id='b09685ee-f918-4b74-a54e-ad8d29ee5ef7' and verification_status not in ('verified_against_standard','corrected');
-- dichtheitspruefung_bestanden
update public.fields set verification_status='verified_against_standard', verification_quote='Die vollständig installierte Grauwassernutzungsanlage muss vor Inbetriebnahme nach den Empfehlungen des Planers überprüft werden. | Das Sammlungs- und Verteilungssystem muss gespült werden und auf Wasserdichtheit (siehe EN 806-4, EN 12056-5, EN 1610) und Querverbindungen zwischen Trink- und Nicht-Trinkwasserleitungen, entweder durch einen Test mit Farbstoff (siehe Beispiel in Anhang C) oder durch einen Drucktest, untersucht werden. — printed p.23', verification_note='md-verified 2026-09-05 (§9, printed p.23 derived) [VC] — "muss" with no gate — STAGED S-6', verified_at=now() where id='df95fb4c-96c4-445b-9c76-e13bcdd0b12d' and verification_status not in ('verified_against_standard','corrected');
-- inbetriebnahmeprotokoll_erstellt
update public.fields set verification_status='verified_against_standard', verification_quote='Ein Inbetriebnahmeprotokoll muss erstellt werden, aus dem ersichtlich ist, dass die Anlage technisch korrekt und vollständig betriebsbereit ist. Das Inbetriebnahmeprotokoll muss dem Eigentümer der Anlage ausgehändigt werden. — printed p.23', verification_note='md-verified 2026-09-05 (§9, printed p.23 derived) [VC]', verified_at=now() where id='d2827286-f516-4bc7-9934-007f4e47b6cd' and verification_status not in ('verified_against_standard','corrected');
-- probenahmestelle_im_verteilsystem
update public.fields set verification_status='verified_against_standard', verification_quote='Die Probenahmestelle muss im Verteilungssystem für das behandelte Grauwasser eingebaut sein. Alle Proben müssen als Stichproben während der laufenden Behandlung im Grauwassersystem entnommen werden. — printed p.23', verification_note='md-verified 2026-09-05 (§11, printed p.23 derived) [VC] — CR-17 tests IS NOT NULL on this boolean (passes on false) — STAGED S-2', verified_at=now() where id='3294e02b-f1a5-49e0-aac1-d710d5504f72' and verification_status not in ('verified_against_standard','corrected');
