-- ######################## DIN-EN-16941-2-05 · Wasserqualitaet, Risikobewertung und Wartung ########################
-- risikobewertung_durchgefuehrt
update public.fields set verification_status='verified_against_standard', verification_quote='Eine Risikobewertung muss durchgeführt werden, um festzustellen, ob die Anlage sicher und zweckmäßig ist. Dies sollte während der Planungsphase erfolgen. | Die Risikobewertung muss die möglichen Auswirkungen der Anlage auf Menschen, die Umwelt und Sachwerte berücksichtigen. | Die Risikobewertung muss Planung, Installation, Prüfung und Inbetriebnahme, Betrieb und Wartung der Anlage, einschließlich Wasserqualität (siehe auch Abschnitt 11), Standsicherheit, elektrische Sicherheit und Zugangsmöglichkeit berücksichtigen. — printed p.23', verification_note='md-verified 2026-09-05 (§10, printed p.23 derived) [VC] — the label''s "in der Planungsphase" is the source''s "sollte" part; the "muss" is the assessment itself', verified_at=now() where id='ed67a0bf-ad20-4eb1-adcc-a243a325b968' and verification_status not in ('verified_against_standard','corrected');
-- wartungsanleitung_verfuegbar
update public.fields set verification_status='verified_against_standard', verification_quote='Für die eingebaute Grauwassernutzungsanlage müssen Wartungsanleitungen verfügbar sein, aufbewahrt und befolgt werden. Diese Anleitungen müssen vollständige Angaben zur Wartung und zu allen Betriebsbedingungen einschließlich Rohranschlüssen, elektrischen Anschlüssen und Inbetriebnahme sowie Verfahren zur Erstinbetriebnahme enthalten. — printed p.24', verification_note='md-verified 2026-09-05 (§12, printed p.24 derived) [VC]', verified_at=now() where id='6fdd3b7a-dfc2-48be-b7c9-7e24afcea6d1' and verification_status not in ('verified_against_standard','corrected');
-- betriebstagebuch_gefuehrt
update public.fields set verification_status='verified_against_standard', verification_quote='Für Grauwassersysteme muss der Eigentümer ein Betriebstagebuch anlegen, insbesondere mit: - Kontaktdaten der Person oder Firma, die mit der Wartung beauftragt ist; - technischen Zeichnungen der Grauwasseranlagenteile, die die Rohrleitungen und Auslaufventile für das Grauwasser-Verteilungssystem und das Trinkwasser-Verteilungssystem zeigen, die er an die Nutzer des Gebäudes schickt; - dem Inbetriebnahmeprotokoll; - dem Datum der durchgeführten Überprüfungen und detaillierte Auflistung der Wartungsarbeiten. | Der Nutzer/Bediener ist für die Aufbewahrung des Betriebstagebuchs verantwortlich. — printed p.24', verification_note='md-verified 2026-09-05 (§12, printed p.24 derived) [VC]', verified_at=now() where id='91ce8142-b9f1-4c75-9d84-7c3bc365a13b' and verification_status not in ('verified_against_standard','corrected');

