-- Gl.(1) Y_G
update public.equations set verification_quote='Die folgende Gleichung (1) muss zur Bestimmung des Grauwasserertrags, $Y_{\mathrm{G}}$, in Liter je Tag (l/d), angewendet werden: | Y_{\mathrm{G}}=n \cdot\left(Q_{\mathrm{S}} \cdot t_{\mathrm{S}} \cdot u_{\mathrm{S}}+V_{\mathrm{BT}} \cdot u_{\mathrm{BT}}+Q_{\mathrm{HWB}} \cdot t_{\mathrm{HWB}} \cdot u_{\mathrm{HWB}}+V_{\mathrm{WM}} \cdot u_{\mathrm{WM}}+Q_{\mathrm{KS}} \cdot t_{\mathrm{KS}} \cdot u_{\mathrm{KS}}+V_{\mathrm{DW}}\right. \tag{1}\\ \left.\cdot u_{\mathrm{DW}}\right) — printed p.19', verification_note=coalesce(verification_note,'')||' | md-quote 2026-09-05 (§6.2.4.2, printed p.19 derived; formula verbatim as the md prints it (LaTeX, "\tag{1}" line break kept); the encoded V_WM_y/u_WM_y = source V_WM/u_WM) [VC]', verified_at=now() where id='72c7d660-c4c2-42a5-a67f-702dd6de6706' and verification_quote is null;
-- Gl.(2) D_G
update public.equations set verification_quote='Die folgende Gleichung (2) muss für die Bestimmung des Grauwasserbedarfs, $D_{\mathrm{G}}$, in Liter je Tag (l/d) angewendet werden, wenn das behandelte Grauwasser z. B. für die Toiletten- und Urinalspülung, zum Reinigen von Wäsche, zur Gartenbewässerung, für Reinigungsarbeiten usw. genutzt wird. | D_{\mathrm{G}}=n \cdot\left(V_{\mathrm{T}} \cdot u_{\mathrm{T}}+V_{\mathrm{U}} \cdot u_{\mathrm{U}}+V_{\mathrm{WM}} \cdot u_{\mathrm{WM}}\right)+V_{\mathrm{misc}} \tag{2} — printed p.20', verification_note=coalesce(verification_note,'')||' | md-quote 2026-09-05 (§6.2.4.3, printed p.20 derived; formula verbatim as the md prints it; the encoded V_WM_d/u_WM_d = source V_WM/u_WM; the encode-time source_quote ends at "Urinalspülung genutzt wird" — the printed sentence continues "zum Reinigen von Wäsche, zur Gartenbewässerung, für Reinigungsarbeiten usw.") [VC]', verified_at=now() where id='4e9bae2a-d1b9-43d9-975f-b56e99395557' and verification_quote is null;
